/**
 * Story 2.3 + 2.4b + PV2-4.3: Content End-to-End Orchestration
 *
 * Full content pipeline: verification -> approval gate -> fix (with retry loop) -> QA -> PR
 *
 * State machine:
 *   verifying -> awaiting_approval -> fixing -> re_verifying -> complete | escalated
 *
 * Story PV2-4.3 refactor:
 *   - runFixLoop() replaced with call to runRetryLoop() from retry-loop.ts (AC1)
 *   - Content fixes use Content QA profile (QN-1 through QN-5) (AC2)
 *   - Model escalation: Haiku -> Sonnet via content_simple profile (AC3)
 *   - QA feedback included in retry prompts (AC4)
 *   - On exhausted retries: content-specific handoff + comment + label (AC5, AC7)
 *   - createPullRequest() uses safeGitAdd() (AC6, already done in PV2-1.3)
 *
 * Orchestration loop (runContentE2E):
 *   1. Run verifier (content-verify.ts) -> get findings
 *   2. Save state as awaiting_approval with findings, pause session
 *   3. On resume (with approval): run retry loop with content fix subagent
 *   4. Retry loop handles: fix -> QA (content profile) -> quality gate -> model escalation
 *   5. If retry loop succeeds -> create PR via `gh pr create` -> state complete
 *   6. If retry loop fails -> generate handoff, post comment, label issue -> state escalated
 *
 * Resume flow (resumeContentE2E):
 *   1. Load paused workflow state
 *   2. processApproval() -> split approved/rejected
 *   3. runContentRetryLoop() -> retry loop with content context
 *   4. finalizeWorkflow() -> PR or escalation with handoff
 *
 * FR39: No auto-merge -- PR is created for human review only.
 *
 * Exit codes:
 * - 0: Success (workflow completed -- either PR created or escalated)
 * - 1: Failure (could not run pipeline)
 */
import * as path from "node:path";
import * as fs from "node:fs";
import { fileURLToPath } from "node:url";
import { execSync } from "node:child_process";
import { tmpdir } from "node:os";
import { validateFix } from "../lib/validate-fix.js";
import { LIMITS, PATHS, ROUTING } from "../config.js";
import { createWorkflowState, updateWorkflowState, loadWorkflowState, } from "../lib/state.js";
import { saveSession, removeSession, } from "../lib/session.js";
import { runContentVerify, } from "./content-verify.js";
// content-fix.js: no longer importing ContentFinding/ContentFixOutput (unused after PV2-4.3 refactor)
import { isKnownCategory, categoryToFileName } from "../lib/categories.js";
import { detectStaleTranslations } from "../lib/content-pipeline-utils.js";
import { safeGitAdd } from "../lib/git-utils.js";
import { handleWorkflowFailure } from "../lib/audit-trail.js";
import { fetchIssueData, addHandoffLabel } from "../lib/github-utils.js";
import { runRetryLoop, } from "../lib/retry-loop.js";
import { commitHandoff, postHandoffComment, } from "../lib/handoff-generator.js";
// ------------------------------------------------------------------
// Internal Helpers (not exported -- used by both run and resume)
// ------------------------------------------------------------------
/** Resolve repo root from this file's location */
function resolveRepoRoot(override) {
    if (override)
        return override;
    if (process.env.GITHUB_WORKSPACE)
        return process.env.GITHUB_WORKSPACE;
    if (process.env.SDK_REPO_ROOT)
        return process.env.SDK_REPO_ROOT;
    const __dirname = path.dirname(fileURLToPath(import.meta.url));
    return path.resolve(__dirname, "..", "..", "..", "..");
}
/** Convert ContentVerificationResult failures to WorkflowFinding[] */
function verificationToFindings(result, _filePath) {
    return result.summary.all_failures.map((f) => ({
        event_id: f.title.toLowerCase().replace(/\s+/g, "_"),
        event_title: f.title,
        gates_failed: f.codes,
        details: f.details,
        severity: f.codes.some((c) => c.startsWith("F") || c.startsWith("A"))
            ? "high"
            : "medium",
    }));
}
/** Build PR description from retry loop result and content context */
function buildPrDescription(findingSummary, qaSummary, workflowId, fixAttemptsUsed) {
    return [
        "## Content Pipeline Fix",
        "",
        `**Workflow:** \`${workflowId}\``,
        "**Fix attempts:** " + fixAttemptsUsed,
        "",
        "### Findings (from content verifier)",
        findingSummary,
        "",
        "### QA Review",
        qaSummary ?? "QA review data not available",
        "",
        "---",
        "*Generated by SDK content E2E pipeline (Story 2.3 + PV2-4.3). Do NOT auto-merge (FR39).*",
    ].join("\n");
}
/** Create a PR using gh CLI. Returns { prNumber, prUrl } or null on dry-run.
 *  AC6: Uses safeGitAdd() instead of git add -A (already in place since PV2-1.3). */
function createPullRequest(opts) {
    if (opts.dryRun) {
        console.log("[content-e2e] DRY RUN: Would create PR:");
        console.log("  Title: " + opts.title);
        console.log("  Branch: " + opts.branch + " -> " + opts.baseBranch);
        console.log("  Body length: " + opts.body.length + " chars");
        return null;
    }
    try {
        // Stage only allowed file types (replaces dangerous `git add -A` -- PV2-1.3, AC6)
        const addResult = safeGitAdd(opts.cwd);
        if (addResult.staged.length === 0) {
            console.log("[content-e2e] No allowed files to stage after safe filtering");
            console.log("[content-e2e] Excluded files: " + addResult.excluded.length);
            throw new Error("No allowed files to stage -- safe git add filtered everything");
        }
        console.log("[content-e2e] Safe git add: " + addResult.staged.length + " files staged, " + addResult.excluded.length + " excluded");
        execSync('git commit -m "fix(content): automated content fix from SDK pipeline"', { cwd: opts.cwd, encoding: "utf-8" });
        execSync(`git push -u origin ${opts.branch}`, {
            cwd: opts.cwd,
            encoding: "utf-8",
        });
        // Create PR (FR39: no auto-merge)
        const prOutput = execSync(`gh pr create --title ${JSON.stringify(opts.title)} --body ${JSON.stringify(opts.body)} --base ${opts.baseBranch} --head ${opts.branch}`, { cwd: opts.cwd, encoding: "utf-8" }).trim();
        // gh pr create outputs the PR URL
        const prUrl = prOutput;
        const prNumberMatch = prUrl.match(/\/pull\/(\d+)/);
        const prNumber = prNumberMatch ? parseInt(prNumberMatch[1], 10) : 0;
        console.log("[content-e2e] PR created: " + prUrl);
        return { prNumber, prUrl };
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.error("[content-e2e] Failed to create PR: " + errMsg);
        throw err;
    }
}
// ------------------------------------------------------------------
// Content-Specific Retry Loop Integration (PV2-4.3 AC1-AC5)
// ------------------------------------------------------------------
/**
 * Build a TriageContext for content bugs to pass to runRetryLoop().
 *
 * Content model escalation: Haiku -> Sonnet (AC3).
 * This maps to the content_simple profile in model-router.ts when confidence >= 0.8.
 * Content_simple escalation path: Haiku -> Sonnet (cheapest content path).
 *
 * @param category - The content category being fixed
 * @param approvedFindings - Findings approved for fixing
 */
function buildContentTriageContext(category, approvedFindings) {
    // Content bugs always classify as content_error with high confidence
    // This maps to content_simple in model-router.ts determineBugProfile()
    // content_simple escalation: Haiku -> Sonnet (AC3)
    return {
        classification: "content_error",
        confidence: 0.95, // High confidence -> content_simple profile
        severity: approvedFindings.some((f) => f.severity === "high") ? "high" : "medium",
        reasoning: "Content verification found " + approvedFindings.length +
            " issue(s) in category '" + category + "' requiring automated fix.",
        fileExtensions: [".json"], // Content fixes only touch JSON files
    };
}
/**
 * Build a synthetic issue body from approved findings for the retry loop.
 *
 * The retry loop expects an issue body describing the bug. For content bugs,
 * we build this from the approved verification findings (AC4 -- QA feedback
 * is handled by retry-loop.ts itself).
 */
function buildContentIssueBody(category, filePath, approvedFindings, correctionsLogPath) {
    const parts = [];
    parts.push("## Content Error Report");
    parts.push("");
    parts.push("**Category:** " + category);
    parts.push("**File:** " + filePath);
    parts.push("**Corrections log:** " + correctionsLogPath);
    parts.push("");
    parts.push("## Findings to Fix");
    parts.push("");
    for (let i = 0; i < approvedFindings.length; i++) {
        const f = approvedFindings[i];
        parts.push("### Finding " + (i + 1) + ": " + f.event_title);
        parts.push("- **Gate codes:** [" + f.gates_failed.join(", ") + "]");
        parts.push("- **Severity:** " + f.severity);
        parts.push("- **Details:** " + f.details);
        parts.push("");
    }
    parts.push("## Instructions");
    parts.push("1. Read the source JSON file and locate each event by title");
    parts.push("2. Apply the correction based on the gate code and details");
    parts.push("3. Increment the event's version field by 1");
    parts.push("4. Append a correction entry to the corrections log");
    parts.push("5. Verify the JSON remains valid after all changes");
    return parts.join("\n");
}
/**
 * Run the content fix retry loop using runRetryLoop() from retry-loop.ts (AC1).
 *
 * This replaces the old runFixLoop() that directly called runContentFix().
 * The retry loop handles: model escalation (AC3), QA review with content profile (AC2),
 * quality gate, handoff generation on failure (AC5), and attempt logging.
 */
async function runContentRetryLoop(state, category, gameRepoPath, options) {
    const approvedFindings = state.approved_findings;
    console.log("[content-e2e] Running content retry loop (PV2-4.3)");
    console.log("[content-e2e] Approved findings: " + approvedFindings.length);
    console.log("[content-e2e] Category: " + category);
    console.log("[content-e2e] File: " + options.filePath);
    console.log("");
    // Build content-specific triage context (AC3: Haiku -> Sonnet)
    const triageContext = buildContentTriageContext(category, approvedFindings);
    // Build synthetic issue body from findings (AC4: context for fix subagent)
    const issueBody = buildContentIssueBody(category, options.filePath, approvedFindings, options.correctionsLogPath);
    const issueTitle = "Content fix: " + category + " -- " + approvedFindings.length + " finding(s)";
    // Update state to fixing
    await updateWorkflowState(state.workflow_id, {
        status: "fixing",
    });
    // Delegate to the shared retry loop (AC1)
    // The retry loop handles:
    //   - Model selection/escalation per attempt (AC3: content_simple = Haiku -> Sonnet)
    //   - Fix subagent spawning with bug-fixer.md prompt
    //   - QA review using content profile (AC2: QN-1 through QN-5)
    //     The profile is automatically determined as "content" by model-router.ts
    //     based on fileExtensions=[".json"] in the triage context.
    //   - QA infra retry (PV2-4.1 AC10)
    //   - Quality gate checks
    //   - Handoff generation on exhaustion (AC5)
    //   - Attempt logging
    const retryResult = await runRetryLoop({
        issueNumber: options.issueNumber ?? 0,
        issueTitle,
        issueBody,
        triage: triageContext,
        screenshots: [], // Content bugs do not have screenshots
        gameRepoPath,
        triageComment: null,
        workflowId: state.workflow_id, // Story 3.6 AC2: audit-trail persistence
    });
    return retryResult;
}
/**
 * Post a generic failure comment on the issue (AC7: no silent failures).
 */
function postFailureComment(issueNumber, error) {
    const repo = ROUTING.PRIVATE_REPO;
    const comment = "## Content Fix Pipeline Failed\n\n" +
        "The content fix pipeline could not resolve this issue automatically.\n\n" +
        "**Error:** " + error + "\n\n" +
        "Manual intervention is required.";
    const tmpFile = path.join(tmpdir(), "gh-content-fail-" + issueNumber + "-" + Date.now() + ".md");
    try {
        fs.writeFileSync(tmpFile, comment, "utf-8");
        execSync("gh issue comment " + issueNumber + " --repo " + repo + " --body-file " + tmpFile, { encoding: "utf-8", timeout: 30_000 });
        console.log("[content-e2e] Posted failure comment on issue #" + issueNumber);
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.log("[content-e2e] WARNING: Could not post failure comment: " + errMsg);
    }
    finally {
        try {
            fs.unlinkSync(tmpFile);
        }
        catch { /* cleanup best-effort */ }
    }
}
/**
 * Story 2.0c: Run validate-fix gate between re-verify and PR creation.
 *
 * AC1/AC2: Called in both resumeContentE2E and resumeTranslationE2E
 * AC3: Captures git diff to temp file before calling validateFix
 * AC9: Direct function call, not subprocess
 * AC10: Logs when validate-fix runs, result, and action taken
 *
 * Returns the validation result. Caller handles failure actions.
 */
export function runValidateFixGate(issueNumber, issueBody, issueLabels, gameRepoPath) {
    console.log("[validate-fix-gate] Running pre-PR validation for issue #" + issueNumber);
    // AC3: Capture git diff to temp file
    const diffPath = path.join(tmpdir(), "validate-fix-diff-" + issueNumber + "-" + Date.now() + ".patch");
    try {
        const diffOutput = execSync("git diff HEAD", { cwd: gameRepoPath, encoding: "utf-8", timeout: 30_000 });
        // If git diff HEAD is empty (changes already staged/committed), try --staged
        const diffContent = diffOutput.trim().length > 0
            ? diffOutput
            : execSync("git diff --staged", { cwd: gameRepoPath, encoding: "utf-8", timeout: 30_000 });
        fs.writeFileSync(diffPath, diffContent, "utf-8");
        console.log("[validate-fix-gate] Diff captured to: " + diffPath + " (" + diffContent.length + " bytes)");
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.error("[validate-fix-gate] WARNING: Could not capture diff: " + errMsg);
        // Write empty file so validateFix can detect empty-diff
        fs.writeFileSync(diffPath, "", "utf-8");
    }
    // AC9: Direct function call to validateFix
    const issueData = {
        number: issueNumber,
        body: issueBody,
        labels: issueLabels,
    };
    const result = validateFix(issueData, diffPath);
    // AC10: Log result and action
    if (result.valid) {
        console.log("[validate-fix-gate] PASSED -- proceeding to PR creation");
    }
    else {
        console.log("[validate-fix-gate] FAILED -- reason: " + result.reason);
        console.log("[validate-fix-gate] Details: " + (result.details ?? "none"));
        console.log("[validate-fix-gate] Action: blocking PR creation, posting comment, adding validation-failed label");
    }
    // Cleanup diff file (best-effort)
    try {
        fs.unlinkSync(diffPath);
    }
    catch { /* cleanup best-effort */ }
    return result;
}
/**
 * Story 2.0c: Handle validate-fix failure -- post comment, add/remove labels.
 *
 * AC4: Post comment with failure details
 * AC5: Add validation-failed label (NOT fix-failed)
 * AC6: Remove fix-in-progress label if present
 */
export function handleValidationFailure(issueNumber, result) {
    const repo = ROUTING.PRIVATE_REPO;
    // AC4: Post comment with failure details
    const comment = "## Pre-PR Validation Failed\n\n" +
        "The automated fix was blocked by the validate-fix gate.\n\n" +
        "**Reason:** `" + (result.reason ?? "unknown") + "`\n\n" +
        "**Details:** " + (result.details ?? "No additional details.") + "\n\n" +
        "This issue requires manual review. The same fix will fail validation every time -- retrying will not help.\n\n" +
        "*Label: `validation-failed` added. `fix-in-progress` removed (if present).*";
    const tmpFile = path.join(tmpdir(), "gh-validate-fail-" + issueNumber + "-" + Date.now() + ".md");
    try {
        fs.writeFileSync(tmpFile, comment, "utf-8");
        execSync("gh issue comment " + issueNumber + " --repo " + repo + " --body-file " + tmpFile, { encoding: "utf-8", timeout: 30_000 });
        console.log("[validate-fix-gate] Posted validation-failed comment on issue #" + issueNumber);
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.log("[validate-fix-gate] WARNING: Could not post comment: " + errMsg);
    }
    finally {
        try {
            fs.unlinkSync(tmpFile);
        }
        catch { /* cleanup */ }
    }
    // AC5: Add validation-failed label (NOT fix-failed)
    try {
        execSync("gh issue edit " + issueNumber + " --repo " + repo + " --add-label validation-failed", { encoding: "utf-8", timeout: 15_000 });
        console.log("[validate-fix-gate] Added validation-failed label to issue #" + issueNumber);
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.log("[validate-fix-gate] WARNING: Could not add validation-failed label: " + errMsg);
    }
    // AC6: Remove fix-in-progress label if present
    try {
        execSync("gh issue edit " + issueNumber + " --repo " + repo + " --remove-label fix-in-progress", { encoding: "utf-8", timeout: 15_000 });
        console.log("[validate-fix-gate] Removed fix-in-progress label from issue #" + issueNumber);
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.log("[validate-fix-gate] WARNING: Could not remove fix-in-progress label: " + errMsg);
    }
}
// ------------------------------------------------------------------
// Exported Shared Helpers (AC1)
// ------------------------------------------------------------------
/**
 * Process an approval response against workflow findings.
 *
 * Separates findings into approved and rejected sets based on the approval.
 * If approval action is "reject", all findings are rejected.
 * If approval action is "approve" with no specific indices, all are approved.
 *
 * Extracted from runContentE2E() lines 377-426 for reuse by resumeContentE2E().
 */
export function processApproval(state, approval) {
    const findings = state.findings;
    if (approval.action === "reject") {
        return { approved: [], rejected: findings };
    }
    // Approve all or specific findings
    if (approval.approvedIndices &&
        approval.approvedIndices.length > 0) {
        const approvedSet = new Set(approval.approvedIndices);
        return {
            approved: findings.filter((_, i) => approvedSet.has(i)),
            rejected: findings.filter((_, i) => !approvedSet.has(i)),
        };
    }
    // Approve all
    return { approved: findings, rejected: [] };
}
/**
 * Finalize a workflow: create PR if fixes passed, escalate with handoff if they failed.
 *
 * PV2-4.3 changes:
 *   - Accepts RetryLoopResult instead of the old fix loop result
 *   - On failure: generates content-specific handoff, posts comment, labels issue (AC5, AC7)
 *   - On success: includes QA summary in PR body
 */
export async function finalizeWorkflow(state, gameRepoPath, options) {
    const { retryResult, approvedFindings } = options;
    console.log("");
    if (retryResult.success) {
        console.log("--- Finalize: PR Creation ---");
        // Build PR description
        const findingSummary = approvedFindings
            .map((f) => "- **" +
            f.event_title +
            "** [" +
            f.gates_failed.join(", ") +
            "]: " +
            f.details)
            .join("\n");
        const prBody = buildPrDescription(findingSummary, retryResult.qaSummary, state.workflow_id, retryResult.fixAttemptsUsed);
        const prTitle = "fix(content): " +
            options.category +
            " -- " +
            approvedFindings.length +
            " finding(s) fixed";
        let prNumber = null;
        let prUrl = null;
        try {
            const prResult = createPullRequest({
                title: prTitle,
                body: prBody,
                branch: options.branch,
                baseBranch: options.baseBranch,
                dryRun: options.dryRun,
                cwd: gameRepoPath,
            });
            if (prResult) {
                prNumber = prResult.prNumber;
                prUrl = prResult.prUrl;
            }
        }
        catch (err) {
            const errMsg = err instanceof Error ? err.message : String(err);
            console.error("[content-e2e] PR creation failed: " + errMsg);
            // AC7: Post failure comment on issue
            if (options.issueNumber) {
                postFailureComment(options.issueNumber, "PR creation failed: " + errMsg);
                addHandoffLabel(options.issueNumber);
            }
            await updateWorkflowState(state.workflow_id, {
                status: "complete",
                fix_attempts: retryResult.fixAttemptsUsed,
                pr_number: null,
                error: "PR creation failed: " + errMsg,
            });
            return { prNumber: null, prUrl: null, escalated: false };
        }
        await updateWorkflowState(state.workflow_id, {
            status: "complete",
            fix_attempts: retryResult.fixAttemptsUsed,
            pr_number: prNumber,
            qa_results: retryResult.qaResults,
            attempt_log: retryResult.attemptLogs,
            models_used: retryResult.modelsUsed,
        });
        console.log("[content-e2e] Status: complete");
        console.log("[content-e2e] Workflow " + state.workflow_id + " finished successfully");
        return { prNumber, prUrl, escalated: false };
    }
    else {
        // Escalation -- retry loop exhausted or QA rejected (AC5, AC7)
        console.log("--- Finalize: Escalation ---");
        console.log("[content-e2e] Retry loop failed after " +
            retryResult.fixAttemptsUsed +
            " attempt(s) -- escalating to owner");
        // AC5: Commit handoff document to pipeline/handoffs branch
        if (retryResult.handoffMarkdown && retryResult.handoffFilePath) {
            console.log("[content-e2e] Committing handoff document...");
            try {
                commitHandoff({ markdown: retryResult.handoffMarkdown, filePath: retryResult.handoffFilePath }, gameRepoPath);
            }
            catch (err) {
                const errMsg = err instanceof Error ? err.message : String(err);
                console.log("[content-e2e] WARNING: Could not commit handoff: " + errMsg);
            }
            // AC7: Post handoff as issue comment
            if (options.issueNumber) {
                postHandoffComment(options.issueNumber, retryResult.handoffMarkdown);
            }
        }
        else if (options.issueNumber) {
            // AC7: Even without a handoff document, post a failure comment
            postFailureComment(options.issueNumber, retryResult.error ?? "Unknown error");
        }
        // AC7: Label issue so it is visible
        if (options.issueNumber) {
            addHandoffLabel(options.issueNumber);
        }
        await updateWorkflowState(state.workflow_id, {
            status: "escalated",
            fix_attempts: retryResult.fixAttemptsUsed,
            qa_results: retryResult.qaResults,
            attempt_log: retryResult.attemptLogs,
            models_used: retryResult.modelsUsed,
            error: retryResult.error ?? "Content fix failed after " + retryResult.fixAttemptsUsed + " attempts.",
        });
        console.log("[content-e2e] Status: escalated");
        console.log("[content-e2e] NO PR created (FR39 -- failed fixes do not get PRs)");
        return { prNumber: null, prUrl: null, escalated: true };
    }
}
// ------------------------------------------------------------------
// FR43: Stale Translation Detection (wired into E2E after fix)
// ------------------------------------------------------------------
/**
 * After a successful content fix, detect stale translations for each
 * approved finding. Reads the fixed English source file to get current
 * event versions, then calls detectStaleTranslations() per finding.
 *
 * Results are saved to workflow state so the digest can surface them.
 */
function runStaleTranslationDetection(approvedFindings, category, gameRepoPath) {
    const categoryFileName = categoryToFileName(category);
    if (!categoryFileName) {
        console.log("[content-e2e] FR43: Cannot detect stale translations -- unknown category file for '" + category + "'");
        return null;
    }
    const translationsDir = path.join(gameRepoPath, "Data", "translations");
    if (!fs.existsSync(translationsDir)) {
        console.log("[content-e2e] FR43: No translations directory found at " + translationsDir + " -- skipping stale detection");
        return null;
    }
    // Read the fixed English source to get current event versions and indices
    const enFilePath = path.join(gameRepoPath, "Data", "Events", categoryFileName);
    let enEvents;
    try {
        const raw = fs.readFileSync(enFilePath, "utf-8");
        const data = JSON.parse(raw);
        enEvents = data.events ?? [];
    }
    catch {
        console.log("[content-e2e] FR43: Could not read English source file -- skipping stale detection");
        return null;
    }
    // Aggregate stale translation results across all approved findings
    const aggregated = {
        hasStale: false,
        staleByLang: {},
        totalStale: 0,
        languagesChecked: [],
    };
    for (const finding of approvedFindings) {
        // Find the event index and version by matching title
        const eventIndex = enEvents.findIndex((e) => e.title === finding.event_title);
        if (eventIndex < 0) {
            console.log("[content-e2e] FR43: Event '" + finding.event_title + "' not found in English source -- skipping");
            continue;
        }
        const newEnVersion = enEvents[eventIndex].version ?? 1;
        const result = detectStaleTranslations(finding.event_title, newEnVersion, translationsDir, categoryFileName, { eventIndex });
        // Merge into aggregated result
        if (result.hasStale) {
            aggregated.hasStale = true;
            for (const lang of Object.keys(result.staleByLang)) {
                if (!aggregated.staleByLang[lang]) {
                    aggregated.staleByLang[lang] = [];
                }
                aggregated.staleByLang[lang].push(...result.staleByLang[lang]);
            }
            aggregated.totalStale += result.totalStale;
        }
        // Merge languagesChecked (deduplicate)
        for (const lang of result.languagesChecked) {
            if (!aggregated.languagesChecked.includes(lang)) {
                aggregated.languagesChecked.push(lang);
            }
        }
    }
    if (aggregated.hasStale) {
        console.log("[content-e2e] FR43: Found " + aggregated.totalStale + " stale translation(s) across " +
            Object.keys(aggregated.staleByLang).length + " language(s)");
        for (const lang of Object.keys(aggregated.staleByLang)) {
            console.log("  " + lang.toUpperCase() + ": " + aggregated.staleByLang[lang].length + " stale event(s)");
        }
    }
    else {
        console.log("[content-e2e] FR43: No stale translations detected");
    }
    return aggregated;
}
// ------------------------------------------------------------------
// Main E2E Orchestration (runContentE2E)
// ------------------------------------------------------------------
/**
 * Run the full content E2E pipeline.
 *
 * This function handles the complete flow:
 * - Initial verification
 * - Approval gate (simulated for local/test runs)
 * - Fix application with retry loop (PV2-4.3: uses runRetryLoop())
 * - QA review via content profile (QN-1 through QN-5)
 * - PR creation or escalation with handoff
 *
 * For real GitHub Actions runs, the approval gate would be implemented via
 * session pause/resume with the sdk-content-resume event type.
 * For local/test runs, approval is simulated (approve all findings).
 */
export async function runContentE2E(input, simulatedApproval) {
    const category = input.category ?? "Unknown";
    const repoRoot = resolveRepoRoot(input.repoRoot);
    const dryRun = input.dryRun ?? true;
    const baseBranch = input.baseBranch ?? "main";
    const branch = input.branch ??
        "sdk/content-fix-" + new Date().toISOString().slice(0, 10).replace(/-/g, "");
    console.log("=== Content E2E Orchestration (PV2-4.3) ===");
    console.log("Category: " + category);
    console.log("File: " + input.filePath);
    console.log("Corrections log: " + input.correctionsLogPath);
    console.log("Repo root: " + repoRoot);
    console.log("Dry run: " + dryRun);
    console.log("Branch: " + branch);
    console.log("Max fix attempts: " + LIMITS.MAX_FIX_ATTEMPTS);
    if (input.issue_number) {
        console.log("Issue: #" + input.issue_number);
    }
    console.log("");
    // ---------------------------------------------------
    // Guard: Reject unknown/unrecognized categories (AC8)
    // ---------------------------------------------------
    if (category === "unknown" || category === "Unknown" || !isKnownCategory(category)) {
        const errorMsg = "Cannot run content verification: category '" + category + "' is not recognized. " +
            "Triage may not have identified the affected category.";
        console.error("[content-e2e] " + errorMsg);
        // AC7: Post error comment on the issue
        if (input.issue_number) {
            postFailureComment(input.issue_number, errorMsg);
        }
        return {
            status: "escalated",
            workflowId: "none",
            totalFindings: 0,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: errorMsg,
        };
    }
    // Resolve file path
    const resolvedFilePath = path.isAbsolute(input.filePath)
        ? input.filePath
        : path.resolve(repoRoot, input.filePath);
    const resolvedCorrectionsLog = path.isAbsolute(input.correctionsLogPath)
        ? input.correctionsLogPath
        : path.resolve(repoRoot, input.correctionsLogPath);
    // ---------------------------------------------------
    // Step 1: Create workflow state (AC3: pass issue_number)
    // ---------------------------------------------------
    const state = await createWorkflowState("content_verification", "manual", category, input.issue_number);
    console.log("[content-e2e] Workflow created: " + state.workflow_id);
    console.log("[content-e2e] Status: " + state.status);
    if (state.issue_number) {
        console.log("[content-e2e] Linked to issue: #" + state.issue_number);
    }
    console.log("");
    // ---------------------------------------------------
    // Step 2: Run initial verification
    // ---------------------------------------------------
    console.log("--- Step 1: Initial Verification ---");
    let verifyResult;
    try {
        verifyResult = await runContentVerify({
            filePath: resolvedFilePath,
            category,
        });
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        // Story 3.6 AC4: use handleWorkflowFailure for consistent error recording
        await handleWorkflowFailure(state.workflow_id, {
            error: "Verification failed: " + errMsg,
            targetStatus: "error",
        });
        // AC7: Post failure comment
        if (input.issue_number) {
            postFailureComment(input.issue_number, "Verification failed: " + errMsg);
        }
        return {
            status: "escalated",
            workflowId: state.workflow_id,
            totalFindings: 0,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: "Verification failed: " + errMsg,
        };
    }
    console.log("");
    // Check if there are any findings
    const findings = verificationToFindings(verifyResult, resolvedFilePath);
    if (findings.length === 0) {
        console.log("[content-e2e] No findings -- nothing to fix.");
        await updateWorkflowState(state.workflow_id, {
            status: "complete",
            findings: [],
        });
        return {
            status: "complete",
            workflowId: state.workflow_id,
            totalFindings: 0,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: null,
        };
    }
    console.log("[content-e2e] " + findings.length + " findings from verification");
    // ---------------------------------------------------
    // Step 3: Save state as awaiting_approval, pause
    // ---------------------------------------------------
    await updateWorkflowState(state.workflow_id, {
        status: "awaiting_approval",
        findings,
    });
    console.log("[content-e2e] Status: awaiting_approval");
    // In a real pipeline, we save the session and pause here.
    // For simulated/test runs, we proceed immediately with the simulated approval.
    if (!simulatedApproval) {
        // Save session for later resume (real pipeline path)
        await saveSession(state.workflow_id, "sim-" + state.workflow_id, "fix_approved_findings");
        console.log("[content-e2e] Session paused -- awaiting human approval");
        console.log("[content-e2e] Resume with: orchestrator resume --issue " +
            (state.issue_number ?? "?") +
            " --action approve");
        return {
            status: "awaiting_approval",
            workflowId: state.workflow_id,
            totalFindings: findings.length,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: null,
        };
    }
    // ---------------------------------------------------
    // Step 4: Process approval (using shared helper)
    // ---------------------------------------------------
    console.log("");
    console.log("--- Step 2: Approval Processing ---");
    // Load fresh state (has findings stored)
    const currentState = await loadWorkflowState(state.workflow_id);
    if (!currentState) {
        const reloadError = "Could not reload workflow state after approval processing";
        // AC7: Post failure comment on issue
        if (input.issue_number) {
            postFailureComment(input.issue_number, reloadError);
            addHandoffLabel(input.issue_number);
        }
        return {
            status: "escalated",
            workflowId: state.workflow_id,
            totalFindings: findings.length,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: reloadError,
        };
    }
    const { approved, rejected } = processApproval(currentState, simulatedApproval);
    if (simulatedApproval.action === "reject") {
        console.log("[content-e2e] Findings rejected: " +
            (simulatedApproval.rejectionReason ?? "no reason"));
        await updateWorkflowState(state.workflow_id, {
            status: "complete",
            rejected_findings: findings,
        });
        return {
            status: "complete",
            workflowId: state.workflow_id,
            totalFindings: findings.length,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: null,
        };
    }
    console.log("[content-e2e] Approved: " + approved.length + " findings");
    if (rejected.length > 0) {
        console.log("[content-e2e] Rejected: " + rejected.length + " findings");
    }
    await updateWorkflowState(state.workflow_id, {
        approved_findings: approved,
        rejected_findings: rejected,
    });
    // ---------------------------------------------------
    // Step 5: Content retry loop (PV2-4.3 AC1)
    // ---------------------------------------------------
    const updatedState = await loadWorkflowState(state.workflow_id);
    if (!updatedState) {
        const retryReloadError = "Could not reload workflow state for retry loop";
        // AC7: Post failure comment on issue
        if (input.issue_number) {
            postFailureComment(input.issue_number, retryReloadError);
            addHandoffLabel(input.issue_number);
        }
        return {
            status: "escalated",
            workflowId: state.workflow_id,
            totalFindings: findings.length,
            approvedFindings: approved.length,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: retryReloadError,
        };
    }
    let retryResult;
    try {
        retryResult = await runContentRetryLoop(updatedState, category, repoRoot, {
            dryRun,
            filePath: resolvedFilePath,
            correctionsLogPath: resolvedCorrectionsLog,
            issueNumber: input.issue_number,
        });
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.error("[content-e2e] FATAL: Retry loop threw exception: " + errMsg);
        await updateWorkflowState(state.workflow_id, {
            status: "escalated",
            error: "Content retry loop exception: " + errMsg,
        });
        // AC7: Post failure comment on issue
        if (input.issue_number) {
            postFailureComment(input.issue_number, "Content retry loop crashed: " + errMsg);
            addHandoffLabel(input.issue_number);
        }
        return {
            status: "escalated",
            workflowId: state.workflow_id,
            totalFindings: findings.length,
            approvedFindings: approved.length,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: "Content retry loop exception: " + errMsg,
        };
    }
    // ---------------------------------------------------
    // Step 5b: Stale translation detection (FR43)
    // ---------------------------------------------------
    if (retryResult.success) {
        console.log("");
        console.log("--- Step 5b: Stale Translation Detection (FR43) ---");
        const staleResult = runStaleTranslationDetection(approved, category, repoRoot);
        if (staleResult) {
            await updateWorkflowState(state.workflow_id, {
                stale_translations: staleResult,
            });
        }
    }
    // ---------------------------------------------------
    // Step 6: PR creation or escalation (using shared helper)
    // ---------------------------------------------------
    const finalResult = await finalizeWorkflow(updatedState, repoRoot, {
        dryRun,
        category,
        branch,
        baseBranch,
        retryResult,
        approvedFindings: approved,
        issueNumber: input.issue_number,
    });
    return {
        status: finalResult.escalated ? "escalated" : "complete",
        workflowId: state.workflow_id,
        totalFindings: findings.length,
        approvedFindings: approved.length,
        fixAttempts: retryResult.fixAttemptsUsed,
        prNumber: finalResult.prNumber,
        prUrl: finalResult.prUrl,
        error: finalResult.escalated
            ? retryResult.error ?? "Content fix failed after " + retryResult.fixAttemptsUsed + " attempts."
            : null,
    };
}
// ------------------------------------------------------------------
// Resume E2E Orchestration (AC2)
// ------------------------------------------------------------------
/**
 * Resume a paused content E2E workflow from awaiting_approval state.
 *
 * This is the Option 2 architecture: a SEPARATE entry point that loads
 * existing workflow state and calls the shared helpers.
 *
 * PV2-4.3: Uses runContentRetryLoop() instead of the old runFixLoop().
 *
 * Flow:
 *   1. Load workflow state by workflowId or issue_number
 *   2. Validate state is awaiting_approval
 *   3. processApproval() -> approved/rejected findings
 *   4. If reject: update state, clean up session, done
 *   5. If approve: runContentRetryLoop() -> finalizeWorkflow()
 *   6. Clean up session
 *
 * @param workflowId - Direct workflow ID (used when known)
 * @param approval - Approval response (approve/reject)
 * @param options - Override paths for game repo, corrections log, etc.
 */
export async function resumeContentE2E(workflowId, approval, options) {
    console.log("=== Content E2E Resume (PV2-4.3) ===");
    console.log("Workflow: " + workflowId);
    console.log("Action: " + approval.action);
    console.log("");
    // ---------------------------------------------------
    // Step 1: Load workflow state
    // ---------------------------------------------------
    const state = await loadWorkflowState(workflowId);
    if (!state) {
        const noStateError = "No state file found for workflow: " + workflowId;
        console.error("[resume] " + noStateError);
        // AC7: Cannot post to GitHub -- state was not loaded so issue_number is unknown.
        // This is logged to console only. The caller (GitHub Actions) will surface the failure.
        return {
            status: "escalated",
            workflowId,
            totalFindings: 0,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: noStateError,
        };
    }
    // ---------------------------------------------------
    // Step 2: Validate state is awaiting_approval
    // ---------------------------------------------------
    if (state.status !== "awaiting_approval") {
        const statusError = "Workflow is not in awaiting_approval state (current: " + state.status + ")";
        console.error("[resume] Workflow " + workflowId + " is in status '" + state.status +
            "', expected 'awaiting_approval'");
        // AC7: Post failure comment on issue
        if (state.issue_number) {
            postFailureComment(state.issue_number, statusError);
        }
        return {
            status: state.status,
            workflowId,
            totalFindings: state.findings.length,
            approvedFindings: 0,
            fixAttempts: state.fix_attempts,
            prNumber: state.pr_number,
            prUrl: null,
            error: statusError,
        };
    }
    const category = state.category ?? "Unknown";
    const gameRepoPath = options?.gameRepoPath ?? resolveRepoRoot(PATHS.GAME_REPO);
    const dryRun = options?.dryRun ?? false;
    const baseBranch = options?.baseBranch ?? "main";
    const branch = options?.branch ??
        "sdk/content-fix-" + new Date().toISOString().slice(0, 10).replace(/-/g, "");
    // Resolve corrections log path
    const correctionsLogPath = options?.correctionsLogPath
        ? (path.isAbsolute(options.correctionsLogPath)
            ? options.correctionsLogPath
            : path.resolve(gameRepoPath, options.correctionsLogPath))
        : path.resolve(gameRepoPath, "Data", "corrections", "corrections-log.json");
    // Resolve the file path from state category
    let filePath;
    const { categoryToFilePath } = await import("../lib/categories.js");
    const resolvedPath = categoryToFilePath(category, gameRepoPath);
    if (resolvedPath) {
        filePath = resolvedPath;
    }
    else {
        const categoryError = "Unknown category '" + category + "' -- cannot determine file path for content fix";
        console.error("[resume] " + categoryError);
        // AC7: Post failure comment on issue
        if (state.issue_number) {
            postFailureComment(state.issue_number, categoryError);
            addHandoffLabel(state.issue_number);
        }
        return {
            status: "escalated",
            workflowId,
            totalFindings: state.findings.length,
            approvedFindings: 0,
            fixAttempts: state.fix_attempts,
            prNumber: null,
            prUrl: null,
            error: "Unknown category: " + category,
        };
    }
    console.log("[resume] Category: " + category);
    console.log("[resume] File: " + filePath);
    console.log("[resume] Game repo: " + gameRepoPath);
    console.log("[resume] Dry run: " + dryRun);
    console.log("");
    // ---------------------------------------------------
    // Step 3: Process approval (using shared helper)
    // ---------------------------------------------------
    console.log("--- Resume Step 1: Process Approval ---");
    const { approved, rejected } = processApproval(state, approval);
    if (approval.action === "reject") {
        console.log("[resume] Findings rejected: " +
            (approval.rejectionReason ?? "no reason"));
        await updateWorkflowState(workflowId, {
            status: "complete",
            rejected_findings: state.findings,
        });
        await removeSession(workflowId);
        console.log("[resume] Workflow " + workflowId + " rejected and closed");
        return {
            status: "complete",
            workflowId,
            totalFindings: state.findings.length,
            approvedFindings: 0,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: null,
        };
    }
    console.log("[resume] Approved: " + approved.length + " findings");
    if (rejected.length > 0) {
        console.log("[resume] Rejected: " + rejected.length + " findings");
    }
    await updateWorkflowState(workflowId, {
        approved_findings: approved,
        rejected_findings: rejected,
    });
    // ---------------------------------------------------
    // Step 4: Content retry loop (PV2-4.3 AC1)
    // ---------------------------------------------------
    console.log("");
    console.log("--- Resume Step 2: Content Retry Loop ---");
    const updatedState = await loadWorkflowState(workflowId);
    if (!updatedState) {
        const resumeReloadError = "Could not reload workflow state for retry loop";
        // AC7: Post failure comment on issue
        if (state.issue_number) {
            postFailureComment(state.issue_number, resumeReloadError);
            addHandoffLabel(state.issue_number);
        }
        return {
            status: "escalated",
            workflowId,
            totalFindings: state.findings.length,
            approvedFindings: approved.length,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: resumeReloadError,
        };
    }
    let retryResult;
    try {
        retryResult = await runContentRetryLoop(updatedState, category, gameRepoPath, {
            dryRun,
            filePath,
            correctionsLogPath,
            issueNumber: state.issue_number ?? undefined,
        });
    }
    catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        console.error("[resume] FATAL: Retry loop threw exception: " + errMsg);
        await updateWorkflowState(workflowId, {
            status: "escalated",
            error: "Content retry loop exception: " + errMsg,
        });
        // AC7: Post failure on issue
        if (state.issue_number) {
            postFailureComment(state.issue_number, "Content retry loop crashed: " + errMsg);
            addHandoffLabel(state.issue_number);
        }
        await removeSession(workflowId);
        return {
            status: "escalated",
            workflowId,
            totalFindings: state.findings.length,
            approvedFindings: approved.length,
            fixAttempts: 0,
            prNumber: null,
            prUrl: null,
            error: "Content retry loop exception: " + errMsg,
        };
    }
    // ---------------------------------------------------
    // Step 4b: Stale translation detection (FR43)
    // ---------------------------------------------------
    if (retryResult.success) {
        console.log("");
        console.log("--- Resume Step 2b: Stale Translation Detection (FR43) ---");
        const staleResult = runStaleTranslationDetection(approved, category, gameRepoPath);
        if (staleResult) {
            await updateWorkflowState(workflowId, {
                stale_translations: staleResult,
            });
        }
    }
    // ---------------------------------------------------
    // Step 5: Validate-fix gate (Story 2.0c AC1)
    // ---------------------------------------------------
    if (retryResult.success && state.issue_number) {
        console.log("");
        console.log("--- Resume Step 3: Validate-Fix Gate (2.0c) ---");
        // Fetch issue body and labels for validation
        let issueBody = "";
        let issueLabels = [];
        try {
            const fetched = fetchIssueData(state.issue_number);
            issueBody = fetched.body;
            issueLabels = fetched.labels;
        }
        catch (fetchErr) {
            const fetchMsg = fetchErr instanceof Error ? fetchErr.message : String(fetchErr);
            console.log("[resume] WARNING: Could not fetch issue data for validation: " + fetchMsg);
            // Continue without validation -- non-fatal (issue data fetch is best-effort in resume)
        }
        if (issueBody.length > 0) {
            const validationResult = runValidateFixGate(state.issue_number, issueBody, issueLabels, gameRepoPath);
            // AC7: On failure, do NOT call createPR, exit cleanly
            if (!validationResult.valid) {
                handleValidationFailure(state.issue_number, validationResult);
                await updateWorkflowState(workflowId, {
                    status: "escalated",
                    fix_attempts: retryResult.fixAttemptsUsed,
                    error: "Validate-fix gate failed: " + (validationResult.reason ?? "unknown"),
                });
                await removeSession(workflowId);
                return {
                    status: "escalated",
                    workflowId,
                    totalFindings: state.findings.length,
                    approvedFindings: approved.length,
                    fixAttempts: retryResult.fixAttemptsUsed,
                    prNumber: null,
                    prUrl: null,
                    error: "Validate-fix gate failed: " + (validationResult.reason ?? "unknown") +
                        " -- " + (validationResult.details ?? ""),
                };
            }
        }
    }
    // ---------------------------------------------------
    // Step 6: Finalize (using shared helper)
    // ---------------------------------------------------
    console.log("");
    console.log("--- Resume Step 4: Finalize ---");
    const finalResult = await finalizeWorkflow(updatedState, gameRepoPath, {
        dryRun,
        category,
        branch,
        baseBranch,
        retryResult,
        approvedFindings: approved,
        issueNumber: state.issue_number ?? undefined,
    });
    // Clean up session
    await removeSession(workflowId);
    return {
        status: finalResult.escalated ? "escalated" : "complete",
        workflowId,
        totalFindings: state.findings.length,
        approvedFindings: approved.length,
        fixAttempts: retryResult.fixAttemptsUsed,
        prNumber: finalResult.prNumber,
        prUrl: finalResult.prUrl,
        error: finalResult.escalated
            ? retryResult.error ?? "Content fix failed after " + retryResult.fixAttemptsUsed + " attempts."
            : null,
    };
}
